async function refreshPlannedRuns(control){control.disabled=true;control.textContent='Reading Garmin Connect…';try{const result=await request('/api/garmin/planned/refresh',{});await load();announce(`${result.count} planned running workouts imported from Garmin Connect.`);}catch(error){control.disabled=false;control.textContent='Refresh from Garmin Connect';announce(error.message,true);}}
function oneOffCard(){
  const extras=Object.values(state.registry?.one_off_sessions||{});if(!extras.length)return null;
  const c=node('section',undefined,'card');c.id='one-off';add(c,heading('Additional workouts'),node('p','Separately requested workouts. They do not change the saved training week or its planned minutes.','plan-intro'));
  for(const s of extras){
    const article=node('article',undefined,'session'),entry=Object.values(state.registry.entries).find(e=>e.session_id===s.id),fromChat=s.id.startsWith('oneoff-chat-');
    add(article,node('h3',s.title),node('p',dayLabel(s.date,{weekday:'long',day:'numeric',month:'long'})+' · '+sessionLength(s)),node('p',s.rationale,'session-rationale'));
    const ol=node('ol',undefined,'steps');for(const t of s.steps)ol.append(node('li',`${t.kind} · ${t.unit==='seconds'?fmt(t.value/60)+' min':fmt(t.value)+' m'} · ${t.description} (${t.target.kind==='effort'?t.target.value:t.target.low+'–'+t.target.high+' bpm'})`));
    add(article,ol,refs(s.references),node('div',entry?`Garmin: ${entry.state.replaceAll('_',' ')} · Watch: ${entry.watch_verified_at?'confirmed by user':'verification pending'}`:'Approved local draft · Garmin: not sent','workout-status'));
    if(fromChat){
      const actions=node('div',undefined,'actions');
      if(!entry||['draft','created'].includes(entry.state)){
        const send=button('Send to Garmin Connect',()=>sendChatWorkout(s.id,send));send.disabled=state.status.review_required||state.snapshot?.activities.source!=='garmin';actions.append(send);
        if(state.status.review_required)article.append(node('p','Training inputs changed. Ask the coach for a fresh proposal before sending.','recovery-note'));
      }else if(['creating','creation_uncertain','scheduling','schedule_uncertain'].includes(entry.state)){
        actions.append(button('Check Connect status',reconcileChatWorkouts));
        article.append(node('p','The write outcome is uncertain. Checking Connect is read-only; this app will not retry an upload automatically.','recovery-note'));
      }else if(entry.state==='scheduled'||entry.state==='completed'){
        article.append(node('p','Scheduled in Garmin Connect. Sync your watch through Garmin Connect and check the workout date and steps on the watch.','recovery-note'));
        if(!entry.watch_verified_at)actions.append(button('I see it on my watch',()=>openWatchEditor(s)));
      }
      if(actions.childElementCount)article.append(actions);
    }
    c.append(article);
  }
  return c;
}
