async function reconcileChatWorkouts(){announce('Checking saved workouts in Garmin Connect…');try{await request('/api/workout/reconcile',{});await load();announce('Connect status checked. Any uncertain result remains blocked until positive readback.');}catch(error){await load();announce(error.message,true);}}
function openWatchEditor(session){ui.watchSessionId=session.id;$('#watch-title').textContent='Confirm '+session.title+' on your watch';$('#watch-note').value='';$('#watch-dialog').showModal();$('#watch-note').focus();}
function comparisonGraph(a,b){const m=chartMetrics[ui.metric],sets=[a,b].map(r=>runDetails(r).samples),valid=sets.flat().filter(p=>p.distance_km!=null&&p[ui.metric]!=null);if(!sets.every(s=>s.some(p=>p[ui.metric]!=null&&p.distance_km!=null)))return node('p','Detailed series are not imported for both runs. The saved summary comparison is available above.','empty');const svg=svgNode('svg',{viewBox:'0 0 640 240',class:'chart-svg',role:'img','aria-label':m.label+' comparison by recorded distance'}),values=valid.map(p=>p[ui.metric]),low=Math.min(...values)-4,high=Math.max(...values)+4,max=Math.max(...valid.map(p=>p.distance_km),1),x=p=>45+p.distance_km/max*570,y=p=>ui.metric==='pace_seconds_per_km'?20+(p[ui.metric]-low)/(high-low)*170:190-(p[ui.metric]-low)/(high-low)*170;for(let i=0;i<4;i++)add(svg,svgNode('line',{x1:45,y1:20+i*170/3,x2:615,y2:20+i*170/3,stroke:'#e7edf5'}),svgNode('text',{x:36,y:24+i*170/3,'text-anchor':'end','font-size':9,fill:'#869bb8'},m.format(ui.metric==='pace_seconds_per_km'?low+(high-low)*i/3:high-(high-low)*i/3)));for(const [index,set] of sets.entries()){let d='';for(const p of set){if(p[ui.metric]==null||p.distance_km==null){d+=' ';continue;}const prev=set[set.indexOf(p)-1],move=!prev||prev[ui.metric]==null||prev.distance_km==null;d+=(move?'M':'L')+x(p)+' '+y(p)+' ';}add(svg,svgNode('path',{d,fill:'none',stroke:index?'#9a88c5':'#4a97ec','stroke-width':2}));}for(let i=0;i<5;i++)add(svg,svgNode('text',{x:45+i/4*570,y:210,'text-anchor':'middle','font-size':10,fill:'#869bb8'},fmt(i/4*max)));add(svg,svgNode('text',{x:330,y:235,'text-anchor':'middle','font-size':11,fill:'#869bb8'},'Recorded distance (km) · '+m.label));return svg;}
function showComparison(){const all=runs(),a=selectedRun();if(all.length<2)return announce('Save at least two runs to compare them.');const content=$('#compare-content'),picker=field('Compare with','select','','compare_run');for(const r of all.filter(r=>r.id!==a.id))option(picker.lastChild,r.id,dayLabel(r.local_date)+' · '+runName(r));function fill(){const b=all.find(r=>r.id===picker.lastChild.value),body=node('div'),grid=node('div',undefined,'comparison-metrics');for(const r of [a,b]){const c=node('div'),dl=node('dl');add(c,node('h3',runName(r)),node('small',dayLabel(r.local_date),'muted'));for(const [label,value] of [['Distance',fmt(r.distance_km)+' km'],['Time',duration(r.duration_seconds)],['Avg pace',duration(r.pace_seconds_per_km)+' /km'],['Avg HR',fmt(r.avg_hr_bpm,0)+' bpm']])add(dl,node('dt',label),node('dd',value));add(grid,add(c,dl));}add(body,grid,comparisonGraph(a,b),node('p','Blue: '+dayLabel(a.local_date)+' · Lavender: '+dayLabel(b.local_date)),refs(['activity:'+a.id,'activity:'+b.id]));const previous=content.querySelector('.comparison-body');body.className='comparison-body';if(previous)previous.replaceWith(body);else content.append(body);}content.replaceChildren(node('h2','Compare your runs'),picker);picker.lastChild.addEventListener('change',fill);fill();if(!$('#compare-dialog').open)$('#compare-dialog').showModal();}
const metricLabels={readiness:'Training readiness',training_status:'Training status',acute_load:'Acute load',vo2_max:'VO₂ max'};
function showMetric(key){if(key==='goal')return setView('settings');const content=$('#metric-content');content.replaceChildren();if(key==='activity'){const a=selectedRun();if(!a)return;add(content,node('h2',runName(a)),node('p','Recorded '+dayLabel(a.local_date)+' · '+a.source),node('p','Distance '+fmt(a.distance_km)+' km · Duration '+duration(a.duration_seconds)+' · Mean HR '+fmt(a.avg_hr_bpm,0)+' bpm · Maximum HR '+fmt(a.max_hr_bpm,0)+' bpm'),refs(['activity:'+a.id]),node('p','Summary pace is derived from saved duration and distance. Missing samples do not become a fabricated curve.'));}else{const item=metric(key),title=metricLabels[key]||key;add(content,node('h2',title),node('div',item.value==null?'—':String(item.value).replaceAll('_',' '),'metric-value'),node('p',dateNote(item)));if(key==='acute_load')add(content,loadCard(),node('p','The total-load range and the balance among training categories are separate observations.'));else if(item.value==null)add(content,node('p',missingText(item.missing_reason)));else{const filters=node('div',undefined,'metric-history'),plot=node('div');function fill(days){plot.replaceChildren();const history=(state.details.history[key]||[]).slice(-days);if(history.some(x=>typeof x.value==='number'))add(plot,spark(history.map(h=>typeof h.value==='number'?h.value:null)));for(const item of history.slice(-7))add(plot,node('p',dayLabel(item.date)+' · '+String(item.value??'Not reported')+' '+(item.unit==='status'?'':item.unit)));for(const button of filters.children)button.classList.toggle('active',Number(button.dataset.days)===days);}for(const days of [7,28,90]){const b=button(days===7?'7 days':days===28?'4 weeks':'Available history',()=>fill(days));b.dataset.days=days;filters.append(b);}add(content,filters,plot);fill(28);add(content,node('p','Source: '+item.source_tool+' · Observation '+item.source_id));}}if(key==='readiness')readinessContext(content);if(key==='acute_load')loadContext(content);if(!$('#metric-dialog').open)$('#metric-dialog').showModal();}
function readinessContext(content){const items=[['sleep_factor','Sleep'],['recovery_factor','Recovery'],['load_factor','Load'],['hrv_factor','HRV'],['stress_history_factor','Stress history'],['sleep_history_factor','Sleep history']];if(!items.some(([key])=>contextMetric(key).value!=null))return;const group=node('section',undefined,'metric-context'),list=node('dl',undefined,'factor-list');add(group,node('h3','Garmin readiness factors'));for(const [key,label] of items)add(list,node('dt',label),node('dd',fmt(contextMetric(key).value,0)+'%'));add(group,list,node('p','Garmin recovery: '+fmt(contextMetric('recovery_hours').value,1)+' h · Weekly HRV: '+fmt(contextMetric('weekly_hrv').value,0)+' ms'),node('p','Garmin: '+(contextMetric('readiness_feedback').value||'not reported').replaceAll('_',' ')));const item=metric('readiness');if(item.recorded_at)add(group,node('small','Recorded '+timeLabel(item.recorded_at)));content.append(group);}
function loadContext(content){const chronic=contextMetric('chronic_load'),ratio=contextMetric('load_ratio');if(chronic.value==null&&ratio.value==null)return;const group=node('section',undefined,'metric-context');add(group,node('h3','Chronic load'),node('p',fmt(chronic.value,1)+' load · '+dateNote(chronic)),gauge(chronic,'#7ab99e',Math.max(1000,chronic.value||0,(chronic.recommended_range?.[1]||0)*1.25),'Chronic load'),node('p','Acute/chronic ratio: '+fmt(ratio.value,1)+' · Garmin: '+(contextMetric('load_status').value||'not reported').replaceAll('_',' ')),node('p','This target band belongs to chronic load. The acute-load target was not reported.'),node('small','Source: '+chronic.source_tool+' · '+chronic.source_id));content.append(group);}
function openCoach(){if(!state)return;const panel=$('#coach-panel');panel.hidden=false;$('#open-coach').setAttribute('aria-expanded','true');renderChat();}
function closeCoach(){ $('#coach-panel').hidden=true;$('#open-coach').setAttribute('aria-expanded','false');}
function renderChat(){
  const container=$('#coach-messages');container.replaceChildren();
  const connection=state.coach_connection||{};
  $('#coach-connection').textContent=(connection.configured?`${connection.model||'Claude'} · Saved observations`:'Claude API key needed · Add it to .env')+' · '+(state.snapshot?.activities.source==='fixture'?'Sample context':'Private local context');
  const entries=state.coach_chat?.items||[];
  if(!entries.length&&!ui.job&&!ui.pendingQuestion&&!ui.localMessages.length){
    const intro=add(node('div',undefined,'coach-intro'),node('strong','Your running, in conversation.'),node('p','Ask about the selected run or recent training. Ask the coach to create a workout to send it to Garmin Connect when checks pass.'));
    const suggestions=node('div',undefined,'coach-suggestions');
    for(const [label,question] of [['Explain this run','Explain this run using the saved data.'],['Review my week','Summarize my saved training week and its uncertainties.'],['Create a workout','Create a structured workout for my next available running day after my saved training week. Use my goal and recent results, and leave enough recovery.']])add(suggestions,button(label,()=>askCoach(question)));
    add(container,intro,suggestions);
  }
  for(const entry of entries.slice(-10)){
    add(container,add(node('div',undefined,'chat-message user'),node('small','YOU'),node('span',entry.question)));
    const reply=add(node('div',undefined,'chat-message assistant'),node('small','COACH · AI SUGGESTION'),node('span',entry.result.answer),refs(entry.result.references));
    if(entry.result.action!=='none'){
      const labels={show_trends:'Open trends',show_plan:'Open training plan',compare_runs:'Compare runs'};
      add(reply,add(node('div',undefined,'actions'),button(labels[entry.result.action],()=>{if(entry.result.action==='compare_runs')showComparison();else setView(entry.result.action==='show_trends'?'trends':'plan');})));
    }
    if(entry.result.workout){
      const draft=entry.result.workout;
      add(reply,add(node('div',undefined,'chat-proposal'),badge(entry.illustrative?'Illustrative proposal':'Proposal','amber'),node('h3',draft.title),node('p',dayLabel(draft.date)+' · '+sessionLength(draft)),add(node('div',undefined,'actions'),button('Preview workout',()=>showProposal(entry)))));
    }
    if(entry.auto_send_requested){
      const delivery=entry.delivery;
      const message=delivery?.state==='scheduled'||delivery?.state==='completed'?'Scheduled in Garmin Connect. Sync your watch to receive it.':delivery?.state==='created'?'Created in Garmin Connect; calendar scheduling needs a status check.':delivery?.message?'Automatic send paused: '+delivery.message:'Automatic send status is pending.';
      add(reply,node('p',message,'recovery-note'));
    }
    add(reply,add(node('div',undefined,'actions'),button('Remember insight',()=>openMemoryEditor(null,entry))));
    container.append(reply);
  }
  for(const item of ui.localMessages)add(container,add(node('div',undefined,'chat-message '+item.role),node('small',item.role==='user'?'YOU':'COACH CONNECTION'),node('span',item.text)));
  const pendingMessage=ui.job?.message||ui.pendingQuestion;
  if(pendingMessage)add(container,add(node('div',undefined,'chat-message user'),node('small','YOU'),node('span',pendingMessage)));
  container.scrollTop=container.scrollHeight;
  $('#coach-progress').hidden=!pendingMessage;
  $('#coach-progress').textContent=ui.job?.phase==='publishing'?'Checking and scheduling in Garmin Connect…':ui.job?'Reviewing saved observations…':ui.pendingQuestion?'Sending your message…':'';
  $('#cancel-coach').hidden=!ui.job||ui.job.phase==='publishing';
  $('#send-coach').disabled=!!pendingMessage;
}
function wantsWorkoutCreated(question){return !/\b(draft|proposal|idea|suggest|suggestion|utkast|förslag|idé|don't send|do not send|without sending)\b/i.test(question)&&/^\s*(?:(?:please|coach[,]?|hey coach[,]?)\s+)*(?:(?:can|could|would)\s+you\s+|i want you to\s+|i'd like you to\s+|(?:kan|skulle)\s+du\s+|jag vill att du\s+)?(?:please\s+)?(?:create|build|make|schedule|skapa|schemalägg)\b.{0,100}\b(?:workouts?|training sessions?|runs?|träningspass|löppass)\b/i.test(question);}
async function askCoach(question){if(ui.job||ui.pendingQuestion)return;ui.pendingQuestion=question;openCoach();$('#coach-input').value=question;try{const job=await request('/api/coach',{message:question,activity_id:selectedRun()?.id||null,auto_send:wantsWorkoutCreated(question)});ui.pendingQuestion=null;ui.job=job;$('#coach-input').value='';renderChat();pollCoach();}catch(e){ui.pendingQuestion=null;ui.localMessages.push({role:'user',text:question},{role:'assistant',text:e.message});renderChat();}}
async function pollCoach(){if(!ui.job)return;const id=ui.job.id;try{const job=await request('/api/coach/job?id='+encodeURIComponent(id));if(ui.job?.id!==id)return;if(job.state==='working'){ui.job=job;renderChat();setTimeout(pollCoach,800);return;}const question=ui.job.message;ui.job=null;if(job.state==='complete'){ui.localMessages=[];await load(false);}else ui.localMessages.push({role:'user',text:question},{role:'assistant',text:job.error||'Coach request cancelled.'});renderChat();}catch(e){if(ui.job?.id===id){ui.localMessages.push({role:'user',text:ui.job.message},{role:'assistant',text:e.message});ui.job=null;renderChat();}}}
function render(){if(!state)return;routeMap?.destroy();routeMap=null;if(!runs().some(a=>a.id===ui.runId)){ui.runId=runs()[0]?.id||null;ui.cursor=Math.floor(runDetails(selectedRun()).samples.length/2);}renderSource();renderRail();const names={runs:'Runs',overview:'Overview',plan:'Plan',trends:'Trends',settings:'Settings',history:'Runs'},crumb=$('#breadcrumb');crumb.replaceChildren(node('span',names[ui.view]||'Runs'),node('span','/'),node('strong',ui.view==='overview'?runName(selectedRun()):ui.view==='runs'?'Activity history':'Your workspace'));const root=$('#dashboard');const views={runs:runsView,overview:runWorkspace,plan:planView,trends:trendsView,settings:settingsView,history:historyView};root.replaceChildren((views[ui.view]||runWorkspace)());renderChat();}
async function load(workspace=true){state=await request('/api/dashboard');const resume=state.coach_connection?.active_job;if(!ui.job&&resume){ui.job=resume;openCoach();pollCoach();}if(workspace)render();else renderChat();if($('#workout-dialog').open&&ui.previewId)showSession(ui.previewId,false);}
for(const n of document.querySelectorAll('[data-icon]'))n.append(icon(n.dataset.icon));
for(const b of document.querySelectorAll('[data-view]'))b.addEventListener('click',()=>setView(b.dataset.view));
for(const b of document.querySelectorAll('[data-close]'))b.addEventListener('click',()=>$('#'+b.dataset.close).close());
$('#all-runs').addEventListener('click',()=>setView('runs'));
$('#open-coach').addEventListener('click',()=>$('#coach-panel').hidden?openCoach():closeCoach());
$('#close-coach').addEventListener('click',closeCoach);
$('#coach-form').addEventListener('submit',e=>{e.preventDefault();const question=$('#coach-input').value.trim();if(question)askCoach(question);});
$('#memory-form').addEventListener('submit',async e=>{e.preventDefault();const {item,entry}=ui.memoryEdit||{};const text=$('#memory-text').value.trim();if(!text)return;try{await request(item?'/api/memory/update':'/api/memory/create',item?{id:item.id,revision:item.revision,text}:{kind:entry?'coach_insight':'user_statement',text,chat_id:entry?.id||null});$('#memory-dialog').close();await load();announce('Memory saved. Your plan needs a coach review.');}catch(error){announce(error.message,true);}});
$('#watch-form').addEventListener('submit',async e=>{e.preventDefault();const note=$('#watch-note').value.trim();if(!note)return;try{await request('/api/workout/watch-verified',{session_id:ui.watchSessionId,note});$('#watch-dialog').close();await load();announce('Watch receipt saved as your statement.');}catch(error){announce(error.message,true);}});
$('#cancel-coach').addEventListener('click',async()=>{if(ui.job)try{await request('/api/coach/cancel',{id:ui.job.id});$('#coach-progress').textContent='Cancelling the request…';}catch(e){announce(e.message,true);}});
$('#update').addEventListener('click',()=>$('#update-dialog').showModal());
$('#close-dialog').addEventListener('click',()=>$('#update-dialog').close());
$('#reload').addEventListener('click',async()=>{try{await load();$('#update-dialog').close();announce('Saved results reloaded.');}catch(e){announce(e.message,true);}});
$('#copy-prompt').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#update-prompt').textContent);$('#copy-prompt').textContent='Copied';}catch{$('#copy-prompt').textContent='Select and copy the prompt above';}});
document.addEventListener('input',e=>{
    const form=e.target.closest('#profile form');
    if(!form||!['timezone','distance_km','goal_minutes','target_date','max_minutes','day','other_training','discomfort','notes','baseline_minutes','baseline_date'].includes(e.target.name))return;
    const confirmation=form.querySelector('input[name=confirmed]');
    if(confirmation.checked){confirmation.checked=false;announce('Training details changed. Recheck confirmation before saving.');}
});
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(['runs','overview','plan','trends','settings','history'].includes(view)&&ui.view!==view){ui.view=view==='history'?'runs':view;render();}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#coach-input').focus();openCoach();}if(e.key==='Escape')closeCoach();});
if(['runs','overview','plan','trends','settings','history'].includes(location.hash.slice(1)))ui.view=location.hash.slice(1)==='history'?'runs':location.hash.slice(1);
load().catch(e=>{announce(e.message,true);$('#source-banner').textContent='Saved results could not be loaded';});
